<section ng-controller="hakHonorController" ng-cloak><div class="alert alert-danger" ng-if="errorMessage" ng-bind="errorMessage"></div><div class="alert alert-success" ng-if="successMessage" ng-bind="successMessage"></div><div class="alert alert-info">Hak honor dibuat otomatis saat tagihan mahasiswa diterbitkan dan hanya dapat disetujui setelah tagihan berstatus LUNAS.</div><article class="card sitara-card"><header class="card-header"><h2 class="sitara-card-title">Daftar hak honor</h2><p class="sitara-card-subtitle">Periksa nominal honor dan status pembayaran tagihan pada periode aktif.</p></header><div class="table-responsive"><table class="table sitara-table mb-0"><thead><tr><th>Dosen</th><th>Kegiatan</th><th>Peran</th><th>Tagihan</th><th class="text-end">Bruto</th><th class="text-end">Pajak</th><th class="text-end">Bersih</th><th>Status</th><th>Aksi</th></tr></thead><tbody><tr ng-repeat="x in datas"><td><div class="table-main" ng-bind="x.full_name"></div><small ng-bind="x.nidn||x.nip||'-'"></small></td><td ng-bind="x.activity_name"></td><td ng-bind="x.role_type+' '+x.position_no"></td><td><div class="table-main" ng-bind="x.bill_no||'-'"></div><small ng-bind="x.bill_status||'Belum ada tagihan'"></small></td><td class="text-end" ng-bind="rupiah(x.gross_amount_snapshot)"></td><td class="text-end" ng-bind="rupiah(x.tax_amount)"></td><td class="text-end table-main" ng-bind="rupiah(x.net_amount)"></td><td ng-bind="x.status"></td><td><button class="btn btn-sm btn-outline-success" ng-if="x.status==='DIAJUKAN' && x.bill_status==='LUNAS'" ng-click="approve(x)">Setujui</button><small class="text-muted" ng-if="x.status==='DIAJUKAN' && x.bill_status!=='LUNAS'">Menunggu pelunasan</small></td></tr><tr ng-if="!datas.length"><td colspan="9" class="sitara-empty">Belum ada hak honor. Hak honor akan muncul setelah tagihan mahasiswa diterbitkan.</td></tr></tbody></table></div></article></section>
